SELECT cust.mobis, cust.work_type, sal.avg_sal, cust.review_status, CASE WHEN (cust.work_type = 'Employed (Private Sec.)' AND sal.avg_sal >= 500) THEN 'al' WHEN (cust.work_type = 'Employed (Public Sec./Govern.)' AND sal.avg_sal >= 300) THEN 'al' ELSE 'alma' END AS al_alma FROM dwd_customer cust JOIN (SELECT al_cmusno AS mobis, ROUND(SUM(TUT) / COUNT(AL_CMUSNO), 2) AS avg_sal FROM TB.MAAS_HAR WHERE MAASHARNO IN (SELECT MAASHARNO FROM tb.maas_har m WHERE (UPPER(NVL(ack, ' ')) LIKE '%SALAR%' OR UPPER(NVL(ack, ' ')) LIKE '%WAGE%' OR UPPER(NVL(ack, ' ')) LIKE '%PAGA%' OR UPPER(NVL(ack, ' ')) LIKE '%RROGA%' OR UPPER(NVL(ack, ' ')) LIKE '%PAGE%' OR UPPER(NVL(ack, ' ')) LIKE '%RROGE%' OR UPPER(NVL(ack, ' ')) LIKE '%PAYROL%' OR UPPER(NVL(ack, ' ')) LIKE '%JANAR%' OR UPPER(NVL(ack, ' ')) LIKE '%SHKURT%' OR UPPER(NVL(ack, ' ')) LIKE '%MARS%' OR UPPER(NVL(ack, ' ')) LIKE '%PRILL%' OR UPPER(NVL(ack, ' ')) LIKE '%MAJ%' OR UPPER(NVL(ack, ' ')) LIKE '%QERSHOR%' OR UPPER(NVL(ack, ' ')) LIKE '%KORRIK%' OR UPPER(NVL(ack, ' ')) LIKE '%GUSHT%' OR UPPER(NVL(ack, ' ')) LIKE '%SHTATOR%' OR UPPER(NVL(ack, ' ')) LIKE '%TETOR%' OR UPPER(NVL(ack, ' ')) LIKE '%NENTOR%' OR UPPER(NVL(ack, ' ')) LIKE '%DHJETOR%') AND tar > sysdate - 90) GROUP BY al_cmusno) sal ON cust.mobis = sal.mobis WHERE cust.work_type IN ('Employed (Private Sec.)', 'Employed (Public Sec./Govern.)') AND cust.valid_date = TO_DATE('01-jan-3000', 'DD-MON-YYYY') AND cust.review_status <> 'Terminated'